CREATE TYPE "RetentionCategory" AS ENUM ('CONTACT_IDENTIFIER','CONSENT_EVIDENCE','CONTRACT_ARTIFACT','SETTLEMENT_ARTIFACT','AUDIT_EVENT','RESEARCH_EVIDENCE');
CREATE TYPE "RetentionReviewStatus" AS ENUM ('PENDING','RETAIN','ELIGIBLE_FOR_MANUAL_DELETION','LEGAL_HOLD');
CREATE TABLE "DataRetentionPolicy" ("id" TEXT NOT NULL,"category" "RetentionCategory" NOT NULL,"jurisdictionState" TEXT NOT NULL,"version" INTEGER NOT NULL,"retentionDays" INTEGER NOT NULL,"active" BOOLEAN NOT NULL DEFAULT false,"counselReviewer" TEXT,"counselApprovedAt" TIMESTAMP(3),"counselApprovalEvidenceUrl" TEXT,"ownerApprovedBy" TEXT,"ownerApprovedAt" TIMESTAMP(3),"effectiveAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DataRetentionPolicy_pkey" PRIMARY KEY ("id"),CONSTRAINT "DataRetentionPolicy_positive_days" CHECK ("retentionDays" > 0));
CREATE TABLE "RetentionReviewRecord" ("id" TEXT NOT NULL,"policyId" TEXT NOT NULL,"recordType" TEXT NOT NULL,"recordIdHash" TEXT NOT NULL,"dueAt" TIMESTAMP(3) NOT NULL,"status" "RetentionReviewStatus" NOT NULL DEFAULT 'PENDING',"legalHoldReason" TEXT,"decidedBy" TEXT,"decidedAt" TIMESTAMP(3),"decisionReason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RetentionReviewRecord_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DataRetentionPolicy_category_jurisdictionState_version_key" ON "DataRetentionPolicy"("category","jurisdictionState","version");
CREATE INDEX "DataRetentionPolicy_category_jurisdictionState_active_idx" ON "DataRetentionPolicy"("category","jurisdictionState","active");
CREATE UNIQUE INDEX "DataRetentionPolicy_one_active_per_scope" ON "DataRetentionPolicy"("category","jurisdictionState") WHERE "active" = true;
CREATE UNIQUE INDEX "RetentionReviewRecord_policyId_recordType_recordIdHash_key" ON "RetentionReviewRecord"("policyId","recordType","recordIdHash");
CREATE INDEX "RetentionReviewRecord_status_dueAt_idx" ON "RetentionReviewRecord"("status","dueAt");
ALTER TABLE "RetentionReviewRecord" ADD CONSTRAINT "RetentionReviewRecord_policyId_fkey" FOREIGN KEY ("policyId") REFERENCES "DataRetentionPolicy"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
